# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Timekeeping handoff load retried" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:retry_service_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(Timekeeping::Environment::SERVICE_TOKEN => retry_service_token) { example.run }
  end

  def retry_checkpoint_json
    at = Time.utc(2026, 3, 1, 12)
    entry = { "id" => 300, "company_id" => 5, "version" => 1, "project_id" => 11, "user_id" => 12, "agent_id" => nil,
              "work_date" => Date.new(2026, 3, 2), "duration" => 45.5, "note" => "", "bill_status" => "unbilled",
              "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
              "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
              "discarded_at" => nil, "created_at" => at, "updated_at" => at }
    audit = { "id" => 70, "company_id" => 5, "entry_id" => 300, "actor_type" => "user", "actor_id" => 12,
              "actor_name" => nil, "action" => "create", "before" => nil, "after" => { "duration" => BigDecimal("45.5") },
              "entry_created_at" => at, "created_at" => at }
    Timekeeping::Handoff::Checkpoint.build(tables: {
      "entries" => [entry], "reservations" => [], "invoice_operations" => [],
      "entry_audits" => [audit], "idempotency_records" => []
    }).to_json
  end

  def put_retry_checkpoint(body)
    put "/internal/v1/handoff/checkpoint", params: body,
                                          headers: { "Authorization" => "Bearer #{retry_service_token}",
                                                     "Content-Type" => "application/json" }
    [response.status, response.body]
  end

  # "Loading the same checkpoint twice through Timekeeping's load endpoint gives
  # equal counts and checksums"
  # The client never retries itself, but an operator re-runs a load whose first
  # attempt timed out after it had already committed.
  it "answers a retried load of the same checkpoint with the same counts and checksums and no duplicated rows" do
    Timekeeping::Admission.fence!
    body = retry_checkpoint_json

    first_status, first_body = put_retry_checkpoint(body)
    second_status, second_body = put_retry_checkpoint(body)

    expect([first_status, second_status]).to eq([200, 200])
    first = Timekeeping::Handoff::Checkpoint.from_json(first_body)
    second = Timekeeping::Handoff::Checkpoint.from_json(second_body)
    expect(second.digest).to eq(first.digest)
    expect(Timekeeping::Handoff::Checkpoint.verify(second)).to eq([])
    expect([Entry.count, AuditEvent.count]).to eq([1, 1])
  end
end
